foreach($type in $plan.types){$native=[type]::GetType($type,$true);$values=$plan.values.PSObject.Properties[$type].Value;for($index=0;$index -lt $values.Count;$index++){$value=[Convert]::ChangeType($values[$index],$native,[Globalization.CultureInfo]::InvariantCulture);for($formatIndex=0;$formatIndex -lt $plan.formats.Count;$formatIndex++){$format=[string]::new([char[]]([int[]]$plan.formats[$formatIndex]));foreach($profile in $plan.providers){$referenceProvider=New-Actor $profile $null $null ([int[]]@(99));$arguments=[object[]]::new(2);$arguments[0]=$format;$arguments[1]=$referenceProvider;try{$text=[string]$formattable.Invoke($value,$arguments);$encoded=[Text.Encoding]::UTF8.GetBytes($text);$reference=[ordered]@{ok=$true;textUnits=[int[]][char[]]$text;bytes=[int[]]$encoded}}catch{$reference=Failure $_};$references.Add([ordered]@{type=$type;index=$index;formatIndex=$formatIndex;provider=$profile;result=$reference;calls=$referenceProvider.Calls;requestedTypeMatches=[object]::ReferenceEquals($referenceProvider.LastType,[Globalization.NumberFormatInfo])})
 foreach($route in $plan.routes){$isByte=$route.StartsWith('byte');$isSlice=$route.EndsWith('span');$offset=0;$suffix=0;if($isSlice){if($isByte){$offset=3;$suffix=4}else{$offset=2;$suffix=3}};if($reference.ok){$length=if($isByte){$reference.bytes.Count}else{$reference.textUnits.Count};$capacities=@(0,1,[Math]::Max(0,$length-1),$length,($length+1))|Sort-Object -Unique}else{$capacities=@(0,1,3,7,32)}
